pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // ── virtual-tail-packed-tree-verify-over-paged-kv ── distilled
        // from lucebox PR #651 paged-attn.cu (ggml_paged_attn_ext_tree +
        // the paged_attn_tree_visible ancestor walk + the virtual_tokens
        // sizing; mixed AR/tree batches place compact AR rows first, tree
        // sequence s at ar_rows + s*tree_width; the block table addresses
        // ONLY the prefix pool -- prefix_pool_tokens = tree_scratch_base).
        // Verified against the full PR diff (target/lucebox_81/pr651.diff).
        // Batch 81 / Research 095 A / Plan 039 T5.
        KernelRule {
            rule_id: "virtual-tail-packed-tree-verify-over-paged-kv".to_string(),
            gpu_concept: "Speculative tree verification over a paged KV pool: present the tree candidates as a VIRTUAL TAIL of tree_width tokens appended to each sequence's committed length, so ONE stable online-softmax pass covers committed prefix and candidates together (virtual_tokens = kv_seq_len + tree_width drives partition/grid sizing -- the tail adds partitionable blocks). Per-token address resolution branches by segment: prefix tokens resolve through the block table (logical block -> physical block -> row); tail candidates resolve to tree_scratch_base + slot*stride + node, GATED by an ancestor-visibility walk -- a candidate is visible to a query node iff it lies on that node's parent chain (parents precede children in the flat tree, root parent is -1; a cyclic or out-of-order parent table resolves to no physical row, not garbage). Invisible siblings and padding rows resolve to NO physical row (phys = -1) and contribute the reduction identity -- they are never branched around. The block table only ever addresses the prefix pool (prefix_pool_tokens = tree_scratch_base): uncommitted candidate nodes stay OUT of every sequence's committed block table, so a rejected verify leaves no residue and no phantom tokens. Distinct from tree-verify-recurrent-state-parent-reload (the recurrence twin -- restores the walker's state shard at DFS branch jumps from stored intermediates; this resolves the KV ROWS attention scores consume, uniting two physical stores behind one logical index), from online-softmax-streaming (consumed unchanged over the unified index space -- the decision here is address resolution, not the softmax schedule), from rotated-ring-undo-via-rebind-reference-snapshot (the rejection-side undo; this is the verify-side read path), from kv-window-device-resident-ring-append (decides where the cache lives and what crosses the bus; this decides how a logical token index resolves across two stores with different indirection per segment), and from mirror-ring-store-sliding-window-contiguity (makes ONE store's window contiguous; no single layout unifies two different stores -- indirection must branch per segment).".to_string(),
            ref_shape: "// naive: each tree candidate verified by a SEPARATE attention pass over\n// the committed prefix -- n_cand full prefix scans per query; the other\n// anti-shape (appending candidate rows into the paged block table)\n// pollutes the committed prefix with uncommitted nodes\nfn score_naive(q: &[f32], prefix_rows: &[f32], cand_rows: &[f32],\n               parents: &[i32], n_cand: usize) -> Vec<f32> {\n    let mut out = Vec::with_capacity(n_cand);\n    for node in 0..n_cand {\n        let mut acc = 0.0;\n        for row in prefix_rows {\n            acc += qdot(q, row); // prefix re-scanned once PER candidate\n        }\n        let mut cur = node as i32;\n        while cur != -1 {\n            // ancestors only -- but the walk sits on top of the N scans\n            acc += qdot(q, &cand_rows[cur as usize]);\n            cur = parents[cur as usize];\n        }\n        out.push(acc);\n    }\n    out\n}\nfn qdot(_q: &[f32], _row: &[f32]) -> f32 { 0.0 }".to_string(),
            opt_pattern: "// optimized: ONE pass over a VIRTUAL token space = committed prefix +\n// a virtual tail of n_cand tokens. Prefix rows resolve via the block\n// table; tail candidates via scratch_base + slot*stride + node, GATED\n// by the ancestor-visibility walk; invisible siblings resolve to NO\n// physical row (phys = -1) and contribute the reduction identity.\nfn resolve_row(token: i32, kv_len: i32, table: &[u32], scratch_base: i32,\n               stride: i32, slot: i32, query_node: i32, parents: &[i32],\n               tree_size: i32) -> i32 {\n    if token < kv_len {\n        // prefix segment: block-table indirection\n        let block = table[(token / 64) as usize];\n        (block as i32) * 64 + token % 64\n    } else {\n        // virtual-tail segment: scratch slab + ancestor gate\n        let candidate = token - kv_len;\n        if !ancestor_visible(parents, query_node, candidate, tree_size) {\n            return -1; // no physical row -- contributes nothing\n        }\n        scratch_base + slot * stride + candidate\n    }\n}\nfn ancestor_visible(parents: &[i32], query_node: i32, candidate: i32,\n                    tree_size: i32) -> bool {\n    if candidate < 0 || candidate >= tree_size {\n        return false;\n    }\n    let mut visible = false;\n    let mut cur = query_node;\n    for _ in 0..tree_size {\n        if cur == candidate {\n            visible = true;\n        }\n        if cur < 0 || cur >= tree_size {\n            return false;\n        }\n        let parent = parents[cur as usize];\n        if parent == -1 {\n            return visible; // root reached\n        }\n        if parent < 0 || parent >= cur {\n            return false; // cyclic or out-of-order parent table\n        }\n        cur = parent;\n    }\n    false\n}\n// grid sizing derives from virtual_tokens = kv_len + n_cand: the tail\n// adds partitionable blocks while the block table addresses ONLY the\n// prefix pool (physical blocks = scratch_base / block_size).\nfn virtual_tokens(kv_len: i32, n_cand: i32) -> i32 {\n    kv_len + n_cand\n}".to_string(),
        },

        // ── gdn-transition-replay-log-commit-many ── distilled from
        // lucebox PR #651 gdn-replay-log.cu + gated_delta_net.cu
        // (capture_replay_log -- "The returned tensor owns a compact copy
        // so graph allocation can release the much larger GDN result
        // after capture"; gdn_replay_log_commit_kernel: current =
        // fmaf(key, delta, gate * current); the conv replay kernel;
        // evolved from #642's per-branch form -- #642 is superseded, do
        // not cite separately). Batch 81 / Research 095 B / Plan 039 T5.
        KernelRule {
            rule_id: "gdn-transition-replay-log-commit-many".to_string(),
            gpu_concept: "For a gated-delta recurrence under speculative verification, committing the ACCEPTED tokens needs the state transition ingredients, not the model: the forward kernel journals [gate | key | delta] per (token, head) into a compact row appended to the result tensor -- width = gate_values + 2*S_v (a scalar gate stores 1 value; the per-row-gate variant stores S_v). After posterior selection, ONE kernel replays each lane's accepted prefix onto its physical state slot in token order: current = fmaf(key, delta, gate * current) -- plus the conv-window commit from the journaled conv input. This kills the second target-model forward for accepted tokens. Three decision halves: (1) the journal VIEW OWNS its storage -- capture appends rows to the result tensor and returns a compact view, so graph allocation can free the much larger GDN result after capture (composes with the output-rotation lifetime family); (2) the replay is deliberately SEQUENTIAL over the SELECTED subset -- selection-awareness is the point (per the associative-scan combine-cost doctrine, the cheap scalar fmaf row replay is the correct strategy for a dxd state, not a parallel scan over all drafted tokens); (3) journaling costs one guarded write inside the already-running kernel (a single lane writes the row; never a second kernel) -- the ingredients were being computed anyway. Distinct from tree-verify-recurrent-state-parent-reload (stores per-token state shards for O(1) reload DURING the walk; this journals transition ingredients DURING the forward and replays AFTER selection -- stored quantity, trigger, and avoided alternative all differ), from first-order-affine-recurrence-associative-scan (parallelizes evaluation over ALL tokens; this is sequential over a selected subset -- the commit shape), from write-before-read-state-skips-checkpoint (decides the speculative checkpoint SET; this decides the commit MECHANISM -- no backup at all), from append-cache-rewind-overwrite-in-place (rolls back for re-execution; this never rolls back -- it replays forward the accepted tokens only), and from quadratic-attention-intermediates-recompute-from-linear-saves (saves linear intermediates to recompute a quadratic chain for the BACKWARD; this avoids a whole-model re-forward for speculative COMMIT).".to_string(),
            ref_shape: "// naive: after posterior selection, re-run the ACCEPTED tokens through\n// the model forward to rebuild the recurrent state -- a second\n// full-model forward per verify round\nfn commit_naive(accepted: &[f32], base_state: &[[f32; 4]; 4]) -> [[f32; 4]; 4] {\n    let mut s = *base_state;\n    for token in accepted {\n        // full forward per accepted token: embedding, projections,\n        // attention -- all recomputed JUST to advance the state\n        let (g, k, delta) = forward_transition(token);\n        s = step_state(&s, g, k, &delta);\n    }\n    s\n}\nfn forward_transition(_t: &f32) -> (f32, [f32; 4], [f32; 4]) {\n    (0.0, [0.0; 4], [0.0; 4])\n}\nfn step_state(s: &[[f32; 4]; 4], g: f32, k: [f32; 4], d: &[f32; 4]) -> [[f32; 4]; 4] {\n    let mut out = *s;\n    for col in 0..4 {\n        for row in 0..4 {\n            out[col][row] = k[row] * d[col] + g * s[col][row];\n        }\n    }\n    out\n}".to_string(),
            opt_pattern: "// optimized: the FORWARD kernel journals the transition ingredients\n// [gate | key | delta] per (token, head) as a compact row appended to\n// the result tensor (one guarded write inside the already-running\n// kernel -- never a second kernel); after posterior selection ONE\n// replay kernel advances the accepted prefix in token order:\n// current = fma(key, delta, gate * current). The journal VIEW OWNS its\n// storage, so graph allocation frees the big GDN result after capture.\nstruct ReplayLog {\n    width: usize,\n    rows: Vec<f32>, // [gate | key(4) | delta(4)] per token\n}\nfn journal_width(state_dim: usize, per_row_gate: bool) -> usize {\n    // scalar gate: 1 + 2*state_dim; per-row gate: 3*state_dim\n    if per_row_gate {\n        3 * state_dim\n    } else {\n        1 + 2 * state_dim\n    }\n}\nfn forward_with_journal(tokens: &[f32], log: &mut ReplayLog) {\n    for (t, token) in tokens.iter().enumerate() {\n        let (g, k, v) = project(token);\n        let delta = v; // (v - g * (S^T k)) * beta -- computed anyway\n        let base = t * log.width;\n        log.rows[base] = g[0];\n        for i in 0..4 {\n            // the journal write rides the kernel already computing the\n            // transition -- a single lane writes, no extra dispatch\n            log.rows[base + 1 + i] = k[i];\n            log.rows[base + 5 + i] = delta[i];\n        }\n    }\n}\nfn replay_commit(log: &ReplayLog, accepted: usize, base: &mut [[f32; 4]; 4]) {\n    // selection-aware SEQUENTIAL replay -- the cheap fma row replay is\n    // the correct strategy for a dxd state, not a parallel scan\n    for t in 0..accepted {\n        let row = &log.rows[t * log.width..(t + 1) * log.width];\n        let gate = row[0];\n        for col in 0..4 {\n            for r in 0..4 {\n                base[col][r] = row[1 + r] * row[5 + col] + gate * base[col][r];\n            }\n        }\n    }\n}\nfn project(_t: &f32) -> (Vec<f32>, Vec<f32>, Vec<f32>) {\n    (vec![0.0], vec![0.0; 4], vec![0.0; 4])\n}".to_string(),
        },

        // ── cross-lane-column-packed-projections ── distilled from
        // lucebox PR #651 draft_graph.cpp (draft_pack_columns +
        // draft_lane_columns + build_draft_kv_steps) extended by PR #659
        // (the batched append projections -- one wk/wv per layer for all
        // lanes -- plus the packed dyn-conv coefficient projections; the
        // handoff doc: "Preserve lane-local positions, masks, cache
        // writes, RoPE, attention, and dynamic-convolution history").
        // The draft-compute p50 tables are PR-body numbers (not present
        // in the diffs) -- mechanism verified, tables unverified locally.
        // Batch 81 / Research 095 D / Plan 039 T5.
        KernelRule {
            rule_id: "cross-lane-column-packed-projections".to_string(),
            gpu_concept: "When N concurrent lanes execute the same layer in one round, every op whose second operand is a SHARED WEIGHT is weight-sharing-shaped: concat the lane column tensors along the free axis and issue ONE wide dispatch per weight per layer (input/output projections, gate/up/down FFN matmuls, coefficient projections) -- the weight is read once for all lanes and N skinny GEMMs become one wide GEMM. Lane-independent elementwise ops (norm scale, activation) ride the packed tensor for free. Split back to per-lane column views BEFORE anything consuming a lane-local operand: positions (RoPE), attention masks, cache destination rows (scatter), attention itself (reads each lane's own cache) -- and before lane-COUPLED state such as a temporal convolution history, where adjacent columns belong to different requests and must not influence each other. Re-pack at each subsequent shared-weight boundary (attention output -> output projection; FFN norm -> gate/up/down), so the graph alternates packed-matmul / lane-local segments. Validate before packing that all lanes agree on the packed-axis extent, and keep the single-lane fast path -- packing one column is pure concat overhead. The AXIS-TRANSPOSED fourth member of the same-input family: same-input-gemv-segments-single-launch merges LAUNCHES over one input, same-input-gemv-weight-concat-at-upload merges WEIGHTS, shared-activation-quantize-memo-per-eval caches the TRANSFORMED activation -- all three merge N ops sharing one INPUT; this packs N DIFFERENT inputs over ONE shared weight along the operand's column axis. Distinct from op-major-backward-loop-inversion-batch-sequence-axis and training-forward-shed-decode-loop-shape (free the sequence/position axis within ONE model pass; this frees the LANE axis across concurrent sequences, and the pack/lane-local routing table is the new decision content), from fan-out-shared-input-single-sync (shares the upload, keeps N launches; this eliminates the launches), and from ragged-pack-offset-table-fused-dispatch (ragged segments are unequal and need an offset table; lanes are equal-width columns -- plain concat plus zero-copy view carve-back). Composes with vendor-batched-gemm-contiguity-staging (this MANUFACTURES the contiguous packed layout the vendor fast path requires) and batch-width-routed-dual-tile-twins (this CREATES the batch width that rule routes on).".to_string(),
            ref_shape: "// ANTI-pattern: per-lane projection loop -- identical weights are read\n// once per lane; N lanes => N dispatches per projection per layer, and\n// lane-local ops chained inside the loop keep every chain narrow\nfn step_naive(w: &ProjWeights, lanes: &[LaneState]) -> Vec<Vec<f32>> {\n    let mut outputs = Vec::with_capacity(lanes.len());\n    for lane in lanes {\n        let normed = rms_norm(&lane.hidden);\n        let q = mat_mul(&w.wq, &normed);\n        let k = mat_mul(&w.wk, &normed);\n        let v = mat_mul(&w.wv, &normed);\n        // lane-local operands chained INSIDE the per-lane loop\n        let k = rope(k, &lane.positions);\n        write_cache(&lane.cache, &k, &lane.rows);\n        let attn = attention(&lane.cache, &q, &v, &lane.mask);\n        let attn_out = mat_mul(&w.wo, &attn);\n        outputs.push(add(&lane.hidden, &attn_out));\n    }\n    outputs\n}\nstruct ProjWeights {\n    wq: Vec<f32>,\n    wk: Vec<f32>,\n    wv: Vec<f32>,\n    wo: Vec<f32>,\n}\nstruct LaneState {\n    hidden: Vec<f32>,\n    positions: Vec<i32>,\n    cache: Vec<f32>,\n    rows: Vec<usize>,\n    mask: Vec<f32>,\n}\nfn rms_norm(_x: &[f32]) -> Vec<f32> { vec![0.0] }\nfn mat_mul(_w: &[f32], _x: &[f32]) -> Vec<f32> { vec![0.0] }\nfn rope(_k: Vec<f32>, _p: &[i32]) -> Vec<f32> { vec![0.0] }\nfn write_cache(_c: &[f32], _k: &[f32], _r: &[usize]) {}\nfn attention(_c: &[f32], _q: &[f32], _v: &[f32], _m: &[f32]) -> Vec<f32> { vec![0.0] }\nfn add(_a: &[f32], _b: &[f32]) -> Vec<f32> { vec![0.0] }".to_string(),
            opt_pattern: "// optimized: pack lane COLUMNS along the free axis; ONE wide dispatch\n// per shared weight per layer; split back BEFORE lane-local consumers;\n// re-pack at each shared-weight boundary; keep the single-lane fast path\nfn pack_columns(lanes: &[Vec<f32>]) -> Vec<f32> {\n    let mut packed = Vec::new();\n    for lane in lanes {\n        packed.extend_from_slice(lane); // concat along the column axis\n    }\n    packed\n}\nfn lane_columns(packed: &[f32], q_len: usize, lane: usize) -> &[f32] {\n    // zero-copy carve-back to one lane's column block\n    &packed[lane * q_len..(lane + 1) * q_len]\n}\nfn step_packed(w: &ProjWeights, lanes: &[LaneState]) -> Vec<Vec<f32>> {\n    if lanes.len() == 1 {\n        // single lane: packing is pure concat overhead -- fast path\n        let normed = rms_norm(&lanes[0].hidden);\n        return vec![add(&lanes[0].hidden, &mat_mul(&w.wo, &normed))];\n    }\n    let q_len = lanes[0].hidden.len(); // equal extents validated pre-pack\n    let normed: Vec<Vec<f32>> = lanes.iter().map(|l| rms_norm(&l.hidden)).collect();\n    // weight-sharing-shaped: ONE wide dispatch reads each weight once\n    // for ALL lanes (N per-lane dispatches -> 1 per weight per layer)\n    let packed = pack_columns(&normed);\n    let q_packed = mat_mul(&w.wq, &packed);\n    let k_packed = mat_mul(&w.wk, &packed);\n    let v_packed = mat_mul(&w.wv, &packed);\n    let mut attn_by_lane = Vec::with_capacity(lanes.len());\n    for (index, lane) in lanes.iter().enumerate() {\n        // lane-local semantics resume: positions, masks, cache rows and\n        // the per-lane attention cache are NOT weight-sharing-shaped\n        let q = lane_columns(&q_packed, q_len, index).to_vec();\n        let k = rope(lane_columns(&k_packed, q_len, index).to_vec(), &lane.positions);\n        write_cache(&lane.cache, &k, &lane.rows);\n        let v = lane_columns(&v_packed, q_len, index);\n        attn_by_lane.push(attention(&lane.cache, &q, v, &lane.mask));\n    }\n    // re-pack at the next shared-weight boundary (output projection)\n    let attn_packed = pack_columns(&attn_by_lane);\n    let out_packed = mat_mul(&w.wo, &attn_packed);\n    lanes\n        .iter()\n        .enumerate()\n        .map(|(index, lane)| add(&lane.hidden, lane_columns(&out_packed, q_len, index)))\n        .collect()\n}\nstruct ProjWeights {\n    wq: Vec<f32>,\n    wk: Vec<f32>,\n    wv: Vec<f32>,\n    wo: Vec<f32>,\n}\nstruct LaneState {\n    hidden: Vec<f32>,\n    positions: Vec<i32>,\n    cache: Vec<f32>,\n    rows: Vec<usize>,\n    mask: Vec<f32>,\n}\nfn rms_norm(_x: &[f32]) -> Vec<f32> { vec![0.0] }\nfn mat_mul(_w: &[f32], _x: &[f32]) -> Vec<f32> { vec![0.0] }\nfn rope(_k: Vec<f32>, _p: &[i32]) -> Vec<f32> { vec![0.0] }\nfn write_cache(_c: &[f32], _k: &[f32], _r: &[usize]) {}\nfn attention(_c: &[f32], _q: &[f32], _v: &[f32], _m: &[f32]) -> Vec<f32> { vec![0.0] }\nfn add(_a: &[f32], _b: &[f32]) -> Vec<f32> { vec![0.0] }".to_string(),
        },

        // ── identity-keyed-graph-retention-stable-arena ── distilled
        // from lucebox PR #659 graph_builders.cpp + step_graph.h (the
        // TargetPagedTreeGraphKey tuple: weights ptr + cache ptr +
        // backend + 6 shape ints; the kv axis bucket-quantized
        // ((requested + 255) / 256) * 256; the retained 512 MiB
        // uninit arena -- "vector::resize would zero 512 MiB on the
        // first decode round"; the address SALT loop -- "captured
        // graphs for different T/S buckets never alias in ggml-cuda's
        // topology cache"; park/unpark key-mismatch invalidation; the
        // selector generation counter is a SEPARATE cache's pattern,
        // re-attributed). target_graph_build p50 -99.98% is a PR-body
        // number. Batch 81 / Research 095 F / Plan 039 T5.
        KernelRule {
            rule_id: "identity-keyed-graph-retention-stable-arena".to_string(),
            gpu_concept: "A topology-stable compute graph must be RETAINED across calls, not rebuilt per call -- gate the rebuild on a composite identity key of owner pointers (weights, cache), backend handle, and shape, so a weights reload or cache swap invalidates automatically by pointer mismatch. BUCKET the naturally-drifting axis of the key -- round the kv/context length UP to a fixed granularity (e.g. 256 tokens) -- so ordinary per-round length drift within a bucket does not invalidate; the padded launch length is the price of retention. Keep the metadata arena (the allocation the graph's node/tensor objects live in) alive across rebuilds at a stable base address: the backend's captured-graph/topology cache keys on node ADDRESSES (nodes[0]), so a fresh arena per rebuild silently defeats device-graph replay even when the topology is identical -- and a zeroing resize of a large arena (512 MiB) is its own stall, so use uninitialized storage. Because the retained arena is now shared by DIFFERENT bucket keys, SALT its start with a bucket-shape-proportional number of dummy allocations so two shapes never land at the same addresses and alias (evicting each other) in the address-keyed cache -- retention and salting are two halves of one contract; retention without the salt makes bucket A's rebuild destroy bucket B's captured graph. Retain the graph allocator and its persistent device buffer across rebuilds (free only at explicit park/shutdown), and when shared owners are torn down, bump the generation counter OTHER retained graphs key on. Distinct from captured-graph-bakes-buffer-addresses (governs the graph's baked BUFFER addresses under mutators -- drop on identity change; this ENGINEERS the METADATA-arena address stability an external topology cache keys on, across rebuilds -- the layer above that invalidation discipline), from hot-swap-weights-preserve-autotune-caches (preserves autotune/JIT caches across weight swaps; this preserves the CAPTURED GRAPH itself across serving rounds -- the most expensive artifact), from weight-handle-cache-keyed-by-allocation-identity (keys a cache by EXISTING pointer identity for dedup; this MANUFACTURES identity stability so a FOREIGN cache's pointer key stays valid), from autotune-cache-extract-outlives-owner (salvages a cache across owner destruction via ownership transfer; here the artifact is rebuilt-but-address-stable), and from reset-state-in-place-fill-never-realloc (identity stability to avoid pool churn on reset; this to keep an external CACHE KEY valid).".to_string(),
            ref_shape: "// ANTI-pattern: rebuild the graph every round into a FRESH metadata\n// arena -- node addresses change each round, so the backend's\n// address-keyed graph cache never hits and captured device graphs are\n// discarded every step\nfn verify_round_fresh(backend: &Backend, weights: &Weights, cache: &Cache,\n                      shape: &RoundShape) -> Graph {\n    // fresh malloc each round: defeats device-graph replay by address\n    let arena = Arena::alloc(512 * 1024 * 1024);\n    let mut ctx = Ctx::over_arena(&arena);\n    let graph = build_tree_verify(&mut ctx, weights, cache, shape);\n    // fresh allocator buffer each round: device pool churn\n    let alloc = Gallocr::new(backend);\n    alloc.reserve(&graph);\n    graph\n}\nstruct Backend;\nstruct Weights;\nstruct Cache;\nstruct Graph;\nstruct RoundShape {\n    kv_len: i32,\n    tree_width: i32,\n    n_tree_seqs: i32,\n}\nstruct Arena;\nimpl Arena {\n    fn alloc(_bytes: usize) -> Arena { Arena }\n}\nstruct Ctx;\nimpl Ctx {\n    fn over_arena(_a: &Arena) -> Ctx { Ctx }\n}\nstruct Gallocr;\nimpl Gallocr {\n    fn new(_b: &Backend) -> Gallocr { Gallocr }\n    fn reserve(&self, _g: &Graph) {}\n}\nfn build_tree_verify(_ctx: &mut Ctx, _w: &Weights, _c: &Cache,\n                     _s: &RoundShape) -> Graph { Graph }".to_string(),
            opt_pattern: "// optimized: composite identity key (owner pointers + backend + shape,\n// kv axis BUCKET-quantized) + a RETAINED metadata arena at a stable base\n// address + an address SALT per bucket so two shapes never alias in the\n// address-keyed backend cache\n#[derive(PartialEq, Eq)]\nstruct GraphKey {\n    weights: *const Weights, // owner identity -- a reload swaps it\n    cache: *const Cache,\n    backend: *const Backend,\n    tree_width: i32,\n    n_tree_seqs: i32,\n    kv_bucket: i32, // kv_len rounded UP to 256s: drift stays in-bucket\n}\nstruct StepGraph {\n    key: Option<GraphKey>,\n    meta_arena: Arena, // retained across rebuilds -- never re-alloc'd\n    alloc: Option<Gallocr>,\n}\nimpl StepGraph {\n    fn verify_round(&mut self, backend: &Backend, weights: &Weights,\n                    cache: &Cache, shape: &RoundShape) -> bool {\n        // quantize the drifting axis BEFORE keying\n        let kv_bucket = ((shape.kv_len + 255) / 256) * 256;\n        let key = GraphKey {\n            weights: std::ptr::from_ref(weights),\n            cache: std::ptr::from_ref(cache),\n            backend: std::ptr::from_ref(backend),\n            tree_width: shape.tree_width,\n            n_tree_seqs: shape.n_tree_seqs,\n            kv_bucket,\n        };\n        // retention: same owners + backend + bucketed topology => reuse\n        if self.key.as_ref() == Some(&key) {\n            return true;\n        }\n        // destructure so the arena borrow cannot conflict with the key\n        // write-back below\n        let StepGraph { key, meta_arena, alloc } = self;\n        // rebuild into the RETAINED arena: node addresses stay stable --\n        // exactly what the address-keyed backend cache keys on (nodes[0])\n        let mut ctx = Ctx::over_arena(meta_arena);\n        // SALT the start by bucket shape: two shapes sharing this arena\n        // must never alias in the address-keyed backend cache\n        for _ in 0..(shape.tree_width + shape.n_tree_seqs) {\n            ctx.new_int_dummy();\n        }\n        let graph = build_tree_verify(&mut ctx, weights, cache, shape);\n        if alloc.is_none() {\n            // persistent device buffer -- freed only at park/shutdown\n            *alloc = Some(Gallocr::new(backend));\n        }\n        alloc.as_ref().unwrap().reserve(&graph);\n        *key = Some(key);\n        true\n    }\n}\nstruct Backend;\nstruct Weights;\nstruct Cache;\nstruct Graph;\nstruct RoundShape {\n    kv_len: i32,\n    tree_width: i32,\n    n_tree_seqs: i32,\n}\nstruct Arena;\nimpl Arena {\n    fn alloc(_bytes: usize) -> Arena { Arena }\n}\nstruct Ctx;\nimpl Ctx {\n    fn over_arena(_a: &Arena) -> Ctx { Ctx }\n    fn new_int_dummy(&mut self) {}\n}\nstruct Gallocr;\nimpl Gallocr {\n    fn new(_b: &Backend) -> Gallocr { Gallocr }\n    fn reserve(&self, _g: &Graph) {}\n}\nfn build_tree_verify(_ctx: &mut Ctx, _w: &Weights, _c: &Cache,\n                     _s: &RoundShape) -> Graph { Graph }".to_string(),
        },

        // ── staged-append-rollback-lifo-retry-blocks ── distilled from
        // lucebox PR #651 paged_kv_pool.{h,cpp} (rollback_append +
        // retry_blocks: "Blocks are pushed in reverse logical order, so
        // append() pops the original allocation order and reproduces
        // the same physical rows on retry"; extend_block_table drains
        // retry_blocks FIRST; the test rollback_retry_preserves_mixed_
        // allocation_order pins block_table == {2,3,0} before AND after
        // retry). Batch 81 / Research 095 G / Plan 039 T5.
        KernelRule {
            rule_id: "staged-append-rollback-lifo-retry-blocks".to_string(),
            gpu_concept: "Speculative tokens STAGE into a per-sequence staged list; the pool append makes rows visible but history and position advance only at commit. On rejection, rollback routes the freed blocks onto a per-sequence LIFO retry list -- NOT the GLOBAL free list -- so the RETRY append pops the same physical rows in the same allocation order (LIFO push in reverse logical order = pop in original order). This is the allocator-level mechanism that keeps address-keyed captured graphs and uploaded block-table deltas valid ACROSS a reject+retry cycle: a global free list guarantees neither row identity nor order -- another sequence's append can steal the block between reject and retry. The staged set counts as OWNED for capacity accounting (reserve checks include block_table + retry_blocks + reserved), and release()/reset() drains the retry list back to the global pool -- the rows are private only while the sequence lives. Distinct from captured-graph-bakes-buffer-addresses (STATES the address-stability invariant; this is the allocator MECHANISM that preserves it across a reject+retry cycle), from rotated-ring-undo-via-rebind-reference-snapshot (exact CONTENT undo for a rejected verify -- restore refs and replay the accepted prefix; this guarantees ADDRESS reproduction for the retry with no content restoration at all; complementary halves of the reject path), from append-cache-rewind-overwrite-in-place (logical pointer rewind for re-execution; this never rewinds -- it routes the FREES), from write-before-read-state-skips-checkpoint (ELIDES the checkpoint set; this makes rollback cheap-by-construction -- the retry re-acquires the same rows, nothing to restore), and from reset-state-in-place-fill-never-realloc (identity stability across a statically-known reset set; this across a DYNAMICALLY acquired/released speculative row set -- free-list routing is the only lever).".to_string(),
            ref_shape: "// naive: rollback returns the speculative blocks to the GLOBAL free\n// list -- the retry append gets WHATEVER the allocator hands out next\n// (another sequence may have taken them), so captured graphs keyed on\n// row addresses and uploaded block-table deltas go stale every reject\nstruct Pool {\n    free: Vec<u32>,\n}\nstruct Seq {\n    block_table: Vec<u32>,\n    staged: Vec<u32>,\n}\nimpl Pool {\n    fn rollback_global(&mut self, seq: &mut Seq, n: usize) {\n        for _ in 0..n {\n            let block = seq.block_table.pop().unwrap();\n            // back to the SHARED pool -- any sequence can steal it\n            // before the retry append\n            self.free.push(block);\n        }\n        seq.staged.clear();\n    }\n    fn append(&mut self, seq: &mut Seq, n: usize) {\n        for _ in 0..n {\n            // NOT the same rows -- allocator order decides\n            let block = self.free.pop().unwrap();\n            seq.block_table.push(block);\n        }\n    }\n}".to_string(),
            opt_pattern: "// optimized: rollback routes freed blocks to a per-sequence LIFO retry\n// list (pushed in REVERSE logical order, so the retry pops the ORIGINAL\n// allocation order); the retry append drains retry_blocks FIRST -- the\n// same physical rows, same order, every time. Captured graphs and\n// block-table deltas survive the reject+retry cycle.\nstruct Pool {\n    free: Vec<u32>,\n}\nstruct Seq {\n    block_table: Vec<u32>,\n    retry: Vec<u32>, // LIFO -- private to THIS sequence\n    staged: Vec<u32>,\n}\nimpl Pool {\n    fn rollback_retry_stable(&mut self, seq: &mut Seq, n: usize) {\n        for _ in 0..n {\n            let block = seq.block_table.pop().unwrap();\n            // PRIVATE reservation: visible to capacity accounting,\n            // invisible to other sequences' appends\n            seq.retry.push(block);\n        }\n        seq.staged.clear();\n    }\n    fn append_retry_first(&mut self, seq: &mut Seq, n: usize) {\n        for _ in 0..n {\n            let block = if let Some(b) = seq.retry.pop() {\n                // LIFO pop = original allocation order: row identity\n                // AND order reproduced on retry\n                b\n            } else {\n                self.free.pop().unwrap()\n            };\n            seq.block_table.push(block);\n        }\n    }\n    fn owned_blocks(seq: &Seq) -> usize {\n        // staged rows count as OWNED: reserve checks must include them\n        seq.block_table.len() + seq.retry.len()\n    }\n}".to_string(),
        },

        // ── fail-closed-multi-resource-commit-transaction ── distilled
        // from lucebox PR #651 gdn-replay-log.cu
        // (ggml_backend_cuda_tree_commit_transaction: three VALIDATE
        // passes then three COMMIT_PREVALIDATED passes; "No recoverable
        // error may escape after the first destination changes" +
        // GGML_ABORT; the duplicate-slot bitmap + cudaPointerGetAttributes
        // device checks). Batch 81 / Research 095 H / Plan 039 T5.
        KernelRule {
            rule_id: "fail-closed-multi-resource-commit-transaction".to_string(),
            gpu_concept: "A commit that mutates MULTIPLE device resources (K/V caches + feature rings + recurrent states + block tables) is a transaction with exactly one safe shape: VALIDATE every destination BEFORE the first kernel launch -- device-pointer attributes (every tensor on ONE device), duplicate-destination detection (a seen-bitmap over slot ids), every shape/layout contract, and range checks on all row indices -- then COMMIT_PREVALIDATED (the validation pass and the commit share one implementation; a prevalidated flag skips revalidation). After the FIRST kernel launch NO recoverable error may escape: abort hard. A mixed pre/post-commit state has no valid fallback -- returning an error would let the caller run fallback on half-committed state, leaving rejected tokens persisted in some resources but not others (silent corruption, not a crash). The error policy SWITCH is the decision content: validation failures before any mutation are ordinary recoverable errors; failures after the first mutation are fatal by construction, so the implementation synchronizes and checks every launch BEFORE returning success. Distinct from verify-once-at-trust-boundary (removes DUPLICATE verification events via a capability type; this PLACES validation before a multi-resource mutation boundary and switches error policy after it), from launch-unchecked-caller-owned-size-contract (elides per-launch validation via documented contracts -- the negative-space complement; checks move from per-launch to the one pre-commit seam), from empty-slice-sentinel-launders-shape-violation (fail-loud against ONE sentinel laundering one violation; this is the MULTI-RESOURCE form -- no recoverable error at all may escape post-mutation), from batched-read-slot-membership-decided-at-launch (one decision point for slot membership; this one VALIDATION point for a mutation set, plus the post-commit error-policy half), from collect-then-resolve-snapshot-batch (same two-phase structure, different property -- determinism vs error-ATOMICITY), and from aliased-slot-allocate-replace-fallback-severs-binding (refuses one semantically-wrong fallback at one slot; this generalizes: once ANY mutation launched, ALL error paths abort).".to_string(),
            ref_shape: "// naive: commit each resource independently, returning an error on\n// failure -- after the FIRST mutation a later failure leaves the\n// resources half-committed, and the caller's fallback runs on a mixed\n// state (rejected tokens persist in some resources, not others)\nfn commit_naive(caches: &mut [Vec<u8>], feats: &mut [Vec<u8>],\n                rows: &[i64]) -> Result<(), String> {\n    for (dst, src) in rows.iter().zip(0..rows.len()) {\n        if *dst < 0 || *dst >= caches[0].len() as i64 {\n            // HALF-COMMITTED: earlier rows are already mutated\n            return Err(\"row out of range\".into());\n        }\n        caches[0][*dst as usize] = caches[0][src];\n    }\n    for (dst, src) in rows.iter().zip(0..rows.len()) {\n        if *dst >= feats[0].len() as i64 {\n            // now caches and features DISAGREE -- silent corruption\n            return Err(\"feature row out of range\".into());\n        }\n        feats[0][*dst as usize] = feats[0][src];\n    }\n    Ok(())\n}".to_string(),
            opt_pattern: "// optimized: a multi-resource commit is a TRANSACTION -- VALIDATE every\n// destination across ALL resources first (ranges, duplicate slots), then\n// COMMIT_PREVALIDATED; after the first mutation NO recoverable error may\n// escape (abort): fallback from a mixed pre/post-commit state is\n// impossible by construction\n#[derive(PartialEq, Clone, Copy)]\nenum Mode {\n    Validate,\n    Commit,\n    CommitPrevalidated,\n}\nfn commit_txn(caches: &mut [Vec<u8>], feats: &mut [Vec<u8>],\n              rows: &[i64], slots: &[i32], mode: Mode) -> bool {\n    let prevalidated = mode == Mode::CommitPrevalidated;\n    let commit = mode != Mode::Validate;\n    if !prevalidated {\n        for dst in rows {\n            // validate EVERY resource's destinations BEFORE any mutation\n            if *dst < 0 || *dst >= caches[0].len() as i64 {\n                return false;\n            }\n            if *dst >= feats[0].len() as i64 {\n                return false;\n            }\n        }\n        let mut seen = [false; 64]; // duplicate-destination bitmap\n        for slot in slots {\n            if *slot < 0 {\n                continue; // padding lane\n            }\n            if seen[*slot as usize] {\n                return false; // duplicate destination\n            }\n            seen[*slot as usize] = true;\n        }\n        if !commit {\n            return true; // VALIDATE-only pass succeeded\n        }\n    }\n    // COMMIT: past this line a failure cannot be recovered from --\n    // abort rather than return false (the caller must NOT retry or\n    // fall back: some resources are already mutated)\n    for (dst, src) in rows.iter().zip(0..rows.len()) {\n        caches[0][*dst as usize] = caches[0][src];\n        feats[0][*dst as usize] = feats[0][src];\n    }\n    true\n}\nfn commit_all(caches: &mut [Vec<u8>], feats: &mut [Vec<u8>],\n              rows: &[i64], slots: &[i32]) -> bool {\n    if !commit_txn(caches, feats, rows, slots, Mode::Validate) {\n        return false; // ordinary recoverable failure -- nothing mutated\n    }\n    if !commit_txn(caches, feats, rows, slots, Mode::Commit) {\n        // mixed pre/post-commit state -- no valid fallback exists\n        std::process::abort();\n    }\n    true\n}".to_string(),
        },
        // ── wy-transform-tree-verify-state-free ── distilled from
        // TreeWY (arXiv:2608.20961 §3: the tree-structured WY/UT
        // transform of the gated delta rule; '(I + diag(beta) G) V~ = R'
        // with 'G strictly lower-triangular' under DFS pre-order; the
        // 128x-per-head storage claim at d_k=d_v=128; the honest
        // 'though not yet a throughput win' tree verdict). Batch 82 /
        // Research 096 G / Plan 043 T1.
        KernelRule {
            rule_id: "wy-transform-tree-verify-state-free".to_string(),
            gpu_concept: "Speculative verification over a linear-attention (GDN) layer cannot roll a recurrent state back the way a KV cache rolls a pointer - the state is a lossy summary of the whole prefix - so the shipped default keeps one FULL state snapshot per draft node (k+1 blocks per layer per sequence), and those snapshots CANNOT be shared across tree branches: a wide, high-acceptance tree becomes memory-infeasible. The fix is algebraic: the gated delta rule rewrites as decayed additive attention with a corrected value, S_t = a_t*S_{t-1} + v~_t*k_t^T with pseudo-value v~_t = b_t*(v_t - a_t*S_{t-1}*k_t), so obtaining the pseudo-values WITHOUT walking the recurrence removes the need for intermediate states. Lay the draft's N nodes in DFS PRE-ORDER from the committed state S0 (every ancestor of node t gets a smaller index) and the whole verification collapses to ONE strictly lower-triangular system: (I + diag(b)*G)*V~ = R, with G[t,i] = (g_t/g_i)*(k_t . k_i) over ancestor positions and R[t] = b_t*v_t - b_t*g_t*(S0*k_t). A single forward substitution yields every node's pseudo-value with NO recurrence walk and NO per-node state; on commit reconstruct ONLY the accepted state, S_a = g_a*S0 + sum over i ancestor-of-or-equal a of (g_a/g_i)*v~_i*k_i^T, which becomes the next S0. Storage drops from N+1 state blocks to ONE O(N*d_v) pseudo-value matrix - a 128x smaller object per head at d_k=d_v=128 - for a chain or a tree alike (the system does not change as the tree widens; tree width costs blocks only in the store-all baseline). MEASURED REGIME (B200/vLLM, 175 matched points, Qwen3.5 hybrids): the win is CONDITIONAL on memory pressure - 2-3x lower peak KV at the same load, up to 1.49x throughput and ~40x lower p99 TTFT past the concurrency knee, 0.97-0.99x parity below it (the per-token dip is the price of admitted concurrency, r=-0.88 vs batch growth, not a slower kernel); acceptance length unchanged (mean |delta|=0.039); trees become AFFORDABLE but are NOT a throughput win - the non-capturable tree mask forces piecewise capture whose eviction cost exceeds the mask itself. Distinct from gdn-transition-replay-log-commit-many (the journal/replay half kills the SECOND target forward by replaying accepted prefixes; this kills the per-node STATE MATERIALIZATION - they compose, and ReplaySSM ships the same triangular solve with deferred state writes), from tree-verify-recurrent-state-parent-reload (reloads register state shards from stored per-token intermediates - still materializes lineage states; this never materializes ANY intermediate state), from first-order-affine-recurrence-associative-scan (the SCAN strategy over a pair-space monoid; this is the SOLVE strategy - triangular factorization replaces the recurrence, one blocked solve instead of O(N) sequential steps), from rotated-ring-undo-via-rebind-reference-snapshot (KV-ring undo via reference snapshot - a recurrent state has no ring to rewind), and from staged-append-rollback-lifo-retry-blocks (allocator row-identity for retry - orthogonal mechanism, composes).".to_string(),
            ref_shape: "// naive: full-state snapshotting - advance the recurrence per node and\n// store a FULL state copy at EVERY draft position (N+1 blocks per layer\n// per sequence); snapshots cannot be shared across tree branches, so a\n// wide, high-acceptance tree is memory-infeasible\ntype Node = (f32, f32, Vec<f32>, Vec<f32>); // (alpha, beta, k, v)\nfn verify_with_snapshots(s0: &[f32], nodes: &[Node]) -> Vec<Vec<f32>> {\n    let mut states: Vec<Vec<f32>> = Vec::with_capacity(nodes.len() + 1);\n    let mut cur = s0.to_vec();\n    states.push(cur.clone()); // the committed state\n    for (alpha, beta, k, v) in nodes {\n        let sk: f32 = cur.iter().zip(k).map(|(s, ki)| s * ki).sum();\n        let mut next = vec![0.0f32; cur.len()];\n        for (i, s) in cur.iter().enumerate() {\n            // S_t = alpha*S + beta*(v - alpha*S*k): the delta correction\n            next[i] = alpha * s + beta * (v[i] - alpha * sk);\n        }\n        states.push(next.clone()); // the SNAPSHOT: O(d_v*d_k) per node\n        cur = next;\n    }\n    states // rollback = index into the N+1 stored blocks\n}".to_string(),
            opt_pattern: "// optimized: TreeWY - DFS PRE-ORDER layout (ancestors before descendants)\n// makes the transition system STRICTLY LOWER-TRIANGULAR; ONE forward\n// substitution solves every pseudo-value; store V~ (O(N*d_v), a 128x\n// smaller object per head) and reconstruct ONLY the accepted state on\n// commit - no recurrence walk, no per-node state, tree or chain alike\ntype Node = (f32, f32, Vec<f32>, Vec<f32>); // (alpha, beta, k, v)\nfn verify_state_free(s0: &[f32], nodes: &[Node]) -> Vec<Vec<f32>> {\n    let n = nodes.len();\n    let d = s0.len();\n    // ancestor gram block: G[t][i] = k_t . k_i for ancestor i < t\n    // (DFS pre-order: every ancestor has a smaller index)\n    let mut g = vec![vec![0.0f32; n]; n];\n    for t in 0..n {\n        for i in 0..t {\n            g[t][i] = nodes[t].2.iter().zip(&nodes[i].2)\n                .map(|(a, b)| a * b).sum();\n        }\n    }\n    // (I + diag(beta) G) V~ = R by forward substitution - the ONLY pass;\n    // the system is UNCHANGED as the tree widens\n    let mut pseudo = vec![vec![0.0f32; d]; n];\n    for t in 0..n {\n        let beta = nodes[t].1;\n        let k = &nodes[t].2;\n        let s0k: f32 = s0.iter().zip(k).map(|(s, ki)| s * ki).sum();\n        for col in 0..d {\n            // R[t] = beta*v - beta*g_t*(S0 k_t), then eliminate ancestors\n            let mut acc = beta * nodes[t].3[col] - beta * s0k;\n            for i in 0..t {\n                acc -= beta * g[t][i] * pseudo[i][col];\n            }\n            pseudo[t][col] = acc; // NO state materialized anywhere\n        }\n    }\n    pseudo // store V~ instead of N+1 state blocks\n}\nfn reconstruct_accepted(s0: &[f32], pseudo: &[Vec<f32>], accepted: usize) -> Vec<f32> {\n    // S_a = g_a*S0 + sum over the accepted node's ancestors of\n    // (g_a/g_i)*v~_i - decay ratios elided in the fixture; ONLY this one\n    // state is ever rebuilt, and it becomes the next S0\n    let mut state = s0.to_vec();\n    for i in 0..=accepted {\n        for (scol, pv) in state.iter_mut().zip(&pseudo[i]) {\n            *scol += pv;\n        }\n    }\n    state\n}".to_string(),
        },
        // ── work-scaling-probe-launch-bound ── distilled from
        // Launch-Bound and Substitutable (arXiv:2608.26612 §IV-A3:
        // 'thirty-two-fold increase in work raises latency 1.55x';
        // 5.6-9.0x isolated -> 0.999x end-to-end vs the measured 1.072x
        // ceiling; 'integration-bound, not Amdahl-bound'; the f=7.87%
        // from 81 wrapped record_function modules). Batch 82 /
        // Research 096 D / Plan 043 T1.
        KernelRule {
            rule_id: "work-scaling-probe-launch-bound".to_string(),
            gpu_concept: "Run the work-scaling probe BEFORE optimizing the arithmetic inside an inference pass: multiply the token count by ~32 and read the latency ratio. Measured on OLMoE-1B-7B: going from 128 to 4096 tokens - 32x the work - raised a 246.8 ms pass to 383.4 ms, a factor of 1.55. A pass whose latency is nearly independent of how much arithmetic it performs is not waiting on arithmetic: it is LAUNCH-BOUND, its latency set by a queue of roughly a thousand small sequential kernel launches (the Python-loop expert dispatch over 64 experts x 16 layers), and isolated kernel speedups will not surface end-to-end - fused Triton kernels at 5.6-9.0x isolated returned 0.999x end-to-end against a MEASURED 1.072x Amdahl ceiling (f = 7.87%). The kernels are integration-bound, not Amdahl-bound: Amdahl already accounts for the 92% of runtime the kernels do not touch, and the remaining gap is the launch queue itself. The ceiling must be measured honestly: obtain f by wrapping the ACTUAL modules in profiler record_function ranges (81 modules in the source study), NEVER by matching CUDA kernel names - name-matching undercounts twice (the variance-reduction kernel whose name does not match, AND the extra QK-norm modules: two per attention layer beyond the residual stream's two). Once launch-bound is confirmed, the productive lever is the LAUNCH STRUCTURE - restructure the data-dependent dispatch into a single batched grouped operation - not the arithmetic of the kernels inside it. Distinct from dispatch-cost-sequential-measurement-not-single-op (measures the TRUE per-dispatch cost via the sequential protocol; this is the upstream go/no-go that decides whether dispatch structure dominates at all), from fusion-payback-gated-on-per-dispatch-overhead (predicts one SPECIFIC fusion's payback from dispatches_saved x overhead; this says when ANY arithmetic optimization is dead on arrival), and from debug-stat-full-scan-out-of-hot-path (a hidden O(collection) tax inside a hot path - the complementary diagnosis: arithmetic that grows with store size).".to_string(),
            ref_shape: "// naive: read the isolated kernel speedup and ship the fusion - 8.9x on\n// the microbench 'must' pay off end-to-end (it returned 0.999x)\nfn decide_from_isolated(rms_isolated_speedup: f32) -> bool {\n    rms_isolated_speedup > 2.0 // 'worth it' - the pass is never measured\n}".to_string(),
            opt_pattern: "// optimized: the WORK-SCALING PROBE first - 32x the tokens, read the\n// latency ratio; ~1.55x means LAUNCH-BOUND (the queue of ~1000 sequential\n// launches sets latency; isolated kernel gains are dead on arrival).\n// The Amdahl ceiling comes from WRAPPED MODULE ranges, never kernel-name\n// matching (which undercounts twice).\nfn launch_bound_probe(lat_128_tokens_ms: f32, lat_4096_tokens_ms: f32) -> bool {\n    // 32x the work, ~1.55x the time => NOT arithmetic-bound\n    lat_4096_tokens_ms / lat_128_tokens_ms < 2.0\n}\nfn amdal_ceiling_wrapped_modules(f_share: f32, isolated_speedup: f32) -> f32 {\n    // f from record_function ranges over the ACTUAL modules - the\n    // variance-reduction kernel and the QK-norm extras are both counted\n    1.0 / ((1.0 - f_share) + f_share / isolated_speedup)\n}\nfn decide_ship_fusion(\n    lat_128_tokens_ms: f32,\n    lat_4096_tokens_ms: f32,\n    f_share: f32,\n    isolated_speedup: f32,\n) -> bool {\n    if launch_bound_probe(lat_128_tokens_ms, lat_4096_tokens_ms) {\n        return false; // integration-bound, not Amdahl-bound - restructure\n                     // the launch queue instead (one batched grouped op)\n    }\n    amdal_ceiling_wrapped_modules(f_share, isolated_speedup) > 1.05\n}".to_string(),
        },
        // ── capture-break-count-not-perf-target ── distilled from
        // Launch-Bound §IV-C2 ('zero graph breaks is three times slower
        // than eager'; 23 breaks removed via dynamic-shape capture;
        // 'a traceability diagnostic and not a performance target') +
        // TreeWY §4 (piecewise capture 'evicts the GDN mixer from
        // graphs, making the cost far larger than the mask itself').
        // Batch 82 / Research 096 E / Plan 043 T1.
        KernelRule {
            rule_id: "capture-break-count-not-perf-target".to_string(),
            gpu_concept: "A count of capture/trace-breaking sites (torch.compile graph breaks, CUDA-graph-incompatible ops) is a TRACEABILITY DIAGNOSTIC, not a performance target - and forcing it to zero through dynamic-shape machinery can INVERT the sign. Measured on a real 16-layer MoE checkpoint: eliminating all 23 graph breaks via capture_dynamic_output_shape_ops made the model 3x SLOWER (0.613x and 0.327x vs eager at the two shapes) and raised the first forward pass from ~1 s to ~40 min - unbacked symbolic shapes force the compiler to emit code that handles ANY size, and the per-call guards plus fallback paths cost more than the eager dispatch they replace. The same inversion appears on the capture side (TreeWY, B200/vLLM): a tree-verify mask that cannot be replayed from a CUDA graph drops the whole model to PIECEWISE capture, evicting the mixer kernels from graphs - a cost far larger than the mask itself. The decision: when capture breaks on a data-dependent op, RESTRUCTURE the op into a shape-static form (the data-dependent dispatch becomes ONE padded/batched grouped operation) or ACCEPT the break and stay piecewise - never force full capture through symbolic-shape guards. A break count that moves only because a capture flag moved is not progress; it moves when the OP moves. Distinct from captured-graph-bakes-buffer-addresses (what a captured graph pins - addresses; this is WHEN to capture at all), from capture-region-dispatch-only (the captured region records GPU work only - the scope rule whose piecewise-eviction corollary this is), from identity-keyed-graph-retention-stable-arena (retaining captured graphs across key changes - this says pushing capture further can be a net loss), and from cuda-graph-scalar-via-device-pointer (making scalars capturable - the compatible-op half of this rule's negative space).".to_string(),
            ref_shape: "// naive: treat the graph-break COUNT as the performance target - force\n// capture of every data-dependent site through dynamic-shape machinery\n// until the count hits zero\nstruct CompileReport {\n    graph_breaks: usize,\n    latency_ms: f32,\n}\nfn fix_breaks_by_forcing_capture(mut report: CompileReport) -> CompileReport {\n    report.graph_breaks = 0; // unbacked symbolic shapes: guards + fallbacks\n    report.latency_ms *= 3.0; // measured 3x SLOWER (0.613x / 0.327x vs\n                              // eager); first forward 1 s -> ~40 min\n    report\n}".to_string(),
            opt_pattern: "// optimized: the break count is a TRACEABILITY DIAGNOSTIC, not a target -\n// restructure the data-dependent op into a shape-static batched form, or\n// accept the break and stay piecewise; never force full capture through\n// symbolic-shape guards\nstruct CompileReport {\n    graph_breaks: usize,\n    latency_ms: f32,\n}\nenum CaptureDecision {\n    RestructureToShapeStatic, // the dispatch becomes ONE padded/batched op\n    AcceptBreak,              // piecewise is cheaper than forced capture\n}\nfn decide_on_break(site_is_data_dependent: bool, restructure_cost: f32) -> CaptureDecision {\n    // forcing capture costs ~3x latency + a ~40-minute first compile\n    if site_is_data_dependent && restructure_cost < 3.0 {\n        CaptureDecision::RestructureToShapeStatic\n    } else {\n        CaptureDecision::AcceptBreak\n    }\n}\nfn apply(report: &CompileReport, decision: CaptureDecision) -> CompileReport {\n    let mut r = CompileReport {\n        graph_breaks: report.graph_breaks,\n        latency_ms: report.latency_ms,\n    };\n    match decision {\n        CaptureDecision::RestructureToShapeStatic => {\n            r.graph_breaks -= 1; // the count moves because the OP moved\n        }\n        CaptureDecision::AcceptBreak => {}\n    }\n    r // never via a capture flag\n}".to_string(),
        },

        // ── pad-tail-to-fixed-tile ── distilled from jundot/omlx PR #2966
        // (merged 2026-08-21, f14796f; verified against the PR page + diff
        // + release notes: +29.0% on a 4,095-token prefill with a 2,047-
        // token tail, 415.3 -> 535.8 tok/s; tuner crossover
        // floor(S*G/H)+1 = 1,357; tail probe -5.9% @1,024 / +84.6%
        // @2,047; intermediate-only padding pinned by the diff's
        // slice-back sites + named regression tests). Batch 84 /
        // Research 098 / Plan 045.
        //
        // Distinct from clamp-tile-indices-to-sentinel-discard-at-write
        // (B16 -- bounds guard discarding OOB writes inside ONE dispatch)
        // and from pad-uniform-pod-to-min-binding-size (B30 -- padding to
        // a binding-size minimum, not reusing a resident compute tile).
        KernelRule {
            rule_id: "pad-tail-to-fixed-tile".to_string(),
            gpu_concept: "When a chunked workload's residual tail is large enough to pay for itself, zero-pad ONLY the intermediate tokenwise-projection activation to the already-resident fixed-shape tile, run that tile, and slice the synthetic rows off BEFORE any stateful consumer (recurrence, KV append, later stages) -- prompt tokens, positions, KV, and recurrent state are never extended. Calibrate the crossover offline from measured per-token throughput on both paths (source formula: threshold = floor(S*G/H)+1, S = tile shape, G = GPU-only tail throughput, H = padded-tile hybrid throughput -- 2048 x 349.4 / 527.4 + 1 = 1357) because padding always executes a WHOLE tile: tiny tails still belong on the small-dispatch/fallback path (source probe -5.9% at a half-tile tail, first positive ~1,152 rows, +84.6% near-full; +29.0% end-to-end at a 4,095-token prefill with a 2,047-token tail, 415.3 -> 535.8 tok/s). Zero rows around per-token projections are semantically inert; the model's learned pad TOKEN is not (it advances positions/KV/recurrence) -- pad activations, never the token sequence. Outputs are not bit-identical when the tile path is itself approximate (the source rides an INT8 approximate path) -- this is a throughput rule gated by the state-stripping invariant, not a numerics rule. Distinct from clamp-tile-indices-to-sentinel-discard-at-write (B16 -- a bounds guard discarding OOB writes inside one dispatch, not dispatch-avoidance via padding) and from pad-uniform-pod-to-min-binding-size (B30 -- padding to satisfy a binding-size minimum, not reusing a resident compute tile).".to_string(),
            ref_shape: "// naive: chunked prefill sends every residual tail to a separate\n// small-dispatch / fallback-engine path -- even a near-full tail pays\n// a whole second dispatch + engine round trip\nconst TILE: usize = 2048;\n\nfn prefill(x: &mut [f32], n_tokens: usize) {\n    let full = (n_tokens / TILE) * TILE;\n    for chunk in x[..full].chunks_exact(TILE) {\n        resident_fixed_tile(chunk); // resident fixed-shape dispatch\n    }\n    let tail = &x[full..n_tokens];\n    if !tail.is_empty() {\n        // 4,095-token prefill => 2,047-row tail: ONE row short of a\n        // full tile, yet it re-routes through the fallback engine\n        fallback_small_dispatch(tail);\n    }\n}\nfn resident_fixed_tile(_c: &[f32]) {}\nfn fallback_small_dispatch(_t: &[f32]) {}".to_string(),
            opt_pattern: "// optimized: tuner-calibrated crossover -- pad the tail iff GPU tail\n// time (tail/G) exceeds one padded tile (S/H): threshold = floor(S*G/H)+1\n// (S=2048, G=349.4, H=527.4 => 1357). Padding runs a WHOLE tile, so\n// small tails keep the fallback: measured -5.9% @1024 rows vs +84.6%\n// @2047 -- tail >= threshold is the entire win regime.\nconst TILE: usize = 2048;\nconst PAD_MIN_TAIL: usize = 1357;\n\nfn prefill(x: &mut [f32], n_tokens: usize, scratch: &mut [f32]) {\n    let full = (n_tokens / TILE) * TILE;\n    for chunk in x[..full].chunks_exact(TILE) {\n        resident_fixed_tile(chunk);\n    }\n    let tail_len = n_tokens - full;\n    if tail_len >= PAD_MIN_TAIL {\n        // Pad ONLY the intermediate tokenwise-projection activation:\n        // zero rows are inert for per-row projections. The learned pad\n        // TOKEN is NOT inert -- never pad the token sequence itself.\n        scratch[..TILE].fill(0.0);\n        scratch[..tail_len].copy_from_slice(&x[full..]);\n        let padded = resident_fixed_tile(&scratch[..TILE]);\n        // STRIP-BEFORE-STATEFUL-CONSUMER: synthetic rows sliced off the\n        // projection result BEFORE recurrence / KV append / later stages.\n        x[full..].copy_from_slice(&padded[..tail_len]);\n    } else if tail_len > 0 {\n        fallback_small_dispatch(&x[full..]);\n    }\n    // NEVER-EXTEND-STATE: prompt tokens, positions, KV entries, and\n    // recurrent state keep their TRUE lengths (n_tokens, never TILE).\n}\nfn resident_fixed_tile(_c: &[f32]) -> Vec<f32> { Vec::new() }\nfn fallback_small_dispatch(_t: &[f32]) {}".to_string(),
        },

        // ── token-local-only-approximate-accelerator ── distilled from
        // jundot/omlx PR #3133 (merged 2026-08-27; verified against the
        // PR page: INT8 scoped to the 6,144 token-local z rows, all
        // 10,240 recurrent qkv rows back to checkpoint precision,
        // effective fraction capped 0.45 -> 0.375 and logged; 32K
        // quality restored with byte-reproducible output hashes;
        // +26.3%/+22.7% are PREFILL-THROUGHPUT gains -- the research
        // record's PP gloss corrected at mine time; in-thread
        // corroboration: the over-ceiling split diverged 3/5 probes at
        // 32K while each arm was byte-deterministic). Batch 84 /
        // Research 098 / Plan 045.
        //
        // Distinct from exact-op-parity-for-analytic-backward (phase
        // gate) and from the quantization/dequant-placement family
        // (HOW to place the work vs WHICH consumers may take it).
        KernelRule {
            rule_id: "token-local-only-approximate-accelerator".to_string(),
            gpu_concept: "The delegation boundary for a lossy/approximate fast backend (INT8-requantized accelerator rows, reduced-precision offload) is the STATE HORIZON of what the result feeds, not the offload fraction that fits. Rows consumed and discarded within the same token's forward (token-local) tolerate bounded approximation and keep the throughput win; rows whose output feeds RECURRENT state (carried across tokens -- approximation error compounds O(layers x tokens) through the recurrence) stay on the checkpoint-precision path, and the configured offload fraction is a CEILING capped at that boundary and logged -- never topped up with recurrent rows. Source: jundot/omlx PR #3133 (merged 2026-08-27): the 50% GDN split put 2,048 recurrent qkv rows on the per-output-channel-INT8 accelerator path and caused deterministic 32K quality failures; capping to the 6,144 token-local z rows (effective 37.5%) restored baseline-discriminating 32K retrieval/ordering/code results with byte-reproducible output hashes while retaining the prefill-THROUGHPUT gains (26.3% @4K, 22.7% @32K vs GPU-only, no decode regression -- throughput numbers, never cite them as quality). Independent in-thread corroboration: the over-ceiling split diverged 3/5 probes at 32K while each arm was internally byte-deterministic -- the hazard manifests as replay divergence and looks harmless at short lengths. Lossy-surface doctrine: aggregate metrics can stay flat while long-horizon deterministic quality collapses -- the gate is the recurrent-feeding consumer, not the end-to-end average. Distinct from exact-op-parity-for-analytic-backward (gates approximation on the train-vs-infer PHASE -- this gates on the consumer's STATE HORIZON: per-token vs recurrent-carried) and from the quantization/dequant-placement family (dequant-placement-by-component-traffic-share and siblings decide HOW to place quant/dequant work -- this decides WHICH consumer sites may receive approximate compute at all). ROUTING-SHAPED MEMBER (Batch 94, oMLX PR #3260): resident substitution -- a cold expert displaced by a resident one when its unmodified router probability is within a max-relative-loss threshold; ORIGINAL gate weights retained for the scores and renormalized after selection (selection on adjusted, scoring on original); Qwen-only; 0% exact, 100% resident-set-only; shipped disabled (default 0.0) pending quality eval -- the same disabled-until-evaluated honesty as this rule.".to_string(),
            ref_shape: "// naive: the offload FRACTION alone decides which rows take the\n// approximate accelerator -- regardless of what each row's output feeds\nenum Backend { GpuCheckpoint, AccelInt8 }\n\nfn route_rows(n_rows: usize, offload_fraction: f32) -> Vec<Backend> {\n    let n_accel = ((n_rows as f32) * offload_fraction) as usize;\n    (0..n_rows)\n        .map(|i| if i < n_accel { Backend::AccelInt8 } else { Backend::GpuCheckpoint })\n        .collect()\n}\n\n// the qkv rows landed on the approximate path because the fraction asked\n// for them -- their outputs feed RECURRENT state, so the accelerator's\n// INT8 error compounds across every later token of the prompt\nlet backends = route_rows(10_240, 0.5);\nlet _qkv = project_with(&backends);\nfn project_with(_b: &[Backend]) -> Vec<f32> { Vec::new() }".to_string(),
            opt_pattern: "// optimized: an is_state_local gate at the delegation site -- the row\n// set's STATE HORIZON, not the fraction, picks the backend; the fraction\n// is demoted to a logged ceiling\n#[derive(Copy, Clone, PartialEq)]\nenum StateHorizon { TokenLocal, Recurrent }\n\nfn select_backend(horizon: StateHorizon) -> Backend {\n    match horizon {\n        // token-local: bounded approximation, accelerator throughput kept\n        StateHorizon::TokenLocal => Backend::AccelInt8,\n        // recurrent-carried: approximation compounds across tokens --\n        // the configured fraction is a CEILING here, never filled\n        StateHorizon::Recurrent => Backend::GpuCheckpoint,\n    }\n}\n\n// z rows are token-local -> approximate; ALL qkv rows are recurrent ->\n// checkpoint precision, even when the configured fraction would take them\nlet z_backend = select_backend(StateHorizon::TokenLocal);\nlet qkv_backend = select_backend(StateHorizon::Recurrent);\nlog_capped_offload(0.45, 0.375); // requested vs effective, the cap is loud\nlet _z = project_row_set(z_backend);\nlet _qkv = project_row_set(qkv_backend);\nfn project_row_set(_b: Backend) -> Vec<f32> { Vec::new() }\nfn log_capped_offload(_requested: f32, _effective: f32) {}".to_string(),
        },

        // -- state-normalization-between-updates-breaks-associative-scan --
        // distilled from arXiv:2602.21204 "Test-Time Training with KV
        // Binding Is Secretly Linear Attention" (NVIDIA, ICML 2026)
        // Appendix I (the non-reducibility analysis); corpus record
        // ../katgpt-rs/.research/516_TTT_KVB_Secretly_Linear_Attention.md
        // (katgpt-rs commit 513088cd). Batch 87 / Plan 048 T3 / Issue 054
        // (R1). THEORY-DISTILLED, grade B: the paper's 4.0x layer-
        // throughput / 1.19x training numbers are the authors' LaCT
        // end-to-end runs -- NEVER cite them as if isolated to this
        // mechanism. ZERO in-tree firing population (paper-distilled
        // precedent = B79 itself); negative control grep-verified:
        // riir-gpu expand_and_l2_normalize_heads_f32 normalizes Q/K
        // heads PRE-recurrence => phi-side => in-tree SAFE.
        KernelRule {
            rule_id: "state-normalization-between-updates-breaks-associative-scan".to_string(),
            gpu_concept: "A recurrence whose STATE is normalized between updates breaks chunk-parallel associativity: Norm(A+B) != Norm(A)+Norm(B), so the per-step state is no longer a plain associative sum over history -- h_t becomes a nonlinear, history-dependent function of every prior residual. The mechanism still reads as linear attention (the rank-1 update shape is unchanged), but applying the pair-space prefix scan (first-order-affine-recurrence-associative-scan's opt shape) computes SILENTLY WRONG outputs: the combine aggregates the raw affine pairs and can never reproduce the normalized trajectory, so the scanned outputs diverge from the production sequential loop -- a wrong answer at scan speed, never an error. This is the App-I non-reducibility breaker (arXiv:2602.21204), with the LaCT weight-norm as the live anti-shape: the App-H chunk-parallel prefix-scan form exists ONLY for the static-kernel + no-state-norm + dot-product-loss corner of the TTT-KVB family. Fix-space, in preference order: (a) MOVE the normalization to the q/k side -- a static per-token transform is part of the kernel phi, the state update stays affine, and the scan stays CORRECT (our GDN's expand_and_l2_normalize_heads_f32 normalizes Q/K heads PRE-recurrence: phi-side, in-tree safe); (b) keep state normalization and accept the strictly sequential O(N) loop -- do not pay for a scan harness that cannot parallelize. PROVENANCE DISCIPLINE: theory-distilled from the paper's App-I non-reducibility analysis; grade B -- the paper's 4.0x layer-throughput / 1.19x training numbers are the authors' LaCT end-to-end runs, NEVER cite them as if isolated to this mechanism; zero in-tree firing population today (paper-distilled precedent = B79 itself). Distinct from first-order-affine-recurrence-associative-scan (the positive case: affine => scan; this is the boundary breaker) and from chunk-reset-cumsum (a reset ZEROES the accumulator at chunk boundaries and composes with chunked scans; normalization RESCALES the state every step and breaks associativity outright).".to_string(),
            ref_shape: "// BROKEN: the update normalizes the STATE every step -- h_t =\n// l2n(a_t*h_{t-1} + b_t) per head -- the LaCT weight-norm shape (App I).\n// The update still \"looks\" affine, so someone reaches for the B79\n// pair-space combine; but the normalization is history-dependent STATE\n// rescaling, so pair composition is NOT associative and the scan output\n// is SILENTLY WRONG (the raw affine trajectory, never the normalized one).\nfn l2n2(v: &[f32; 2]) -> [f32; 2] {\n    let n = (v[0] * v[0] + v[1] * v[1]).sqrt().max(1e-6);\n    [v[0] / n, v[1] / n]\n}\nfn combine(later: (f32, f32), earlier: (f32, f32)) -> (f32, f32) {\n    // the B79 combine -- VALID only for the un-normalized affine recurrence\n    (later.0 * earlier.0, later.0 * earlier.1 + later.1)\n}\nfn broken_scan(a: &[f32], b_u: &[f32], n: usize) -> Vec<f32> {\n    // per-channel scan of the raw (a, b) pairs over a state-normalized\n    // recurrence: WRONG at every normalized step -- Norm(a*A + B) !=\n    // a*Norm(A) + Norm(B), so no pairwise aggregation of (a, b) pairs\n    // can reproduce the normalized states.\n    let mut out = vec![0.0f32; 2 * n];\n    for c in 0..2 {\n        let mut pairs: Vec<(f32, f32)> = (0..n).map(|t| (a[t], b_u[t])).collect();\n        let mut stride = 1usize;\n        while stride < n {\n            for i in (stride..n).rev() {\n                pairs[i] = combine(pairs[i], pairs[i - stride]);\n            }\n            stride *= 2;\n        }\n        for t in 0..n {\n            out[t * 2 + c] = pairs[t].1; // the RAW affine h_t -- not the\n        } // normalized h_t the production loop computes. Wrong at speed.\n    }\n    out\n}\n// ground truth is the SEQUENTIAL normalized loop:\n// h = l2n2(&[a[t]*h[0] + b_u[t], a[t]*h[1] + b_u[t]]) each step -- h_t is\n// a nonlinear function of the FULL history; no scan shape computes it.\n".to_string(),
            opt_pattern: "// FIX (a) -- phi-side: normalize q/k BEFORE the recurrence (static\n// per-token transform = part of the kernel phi); the state update stays\n// affine and the B79 scan is CORRECT (our GDN's\n// expand_and_l2_normalize_heads_f32: heads expanded + L2-normed on Q/K,\n// V copied, state untouched).\nfn phi_side(q: &[f32], k: &[f32]) -> Vec<f32> {\n    // project/normalize the TOKEN-side inputs; the state is never touched\n    q.iter().zip(k).map(|(&a, &b)| a * b).collect()\n}\n// h_t = a_t*h_{t-1} + b_t over the UNTOUCHED state -> the B79 scan applies.\n// FIX (b) -- keep state normalization, keep the sequential loop (accept\n// O(N); NEVER wrap it in the scan harness -- log-depth rounds still\n// return the wrong trajectory):\nfn l2n2(v: &[f32; 2]) -> [f32; 2] {\n    let n = (v[0] * v[0] + v[1] * v[1]).sqrt().max(1e-6);\n    [v[0] / n, v[1] / n]\n}\nfn state_normed_sequential(a: &[f32], b_u: &[f32], n: usize) -> Vec<f32> {\n    let mut h = [0.0f32; 2];\n    let mut out = Vec::with_capacity(2 * n);\n    for t in 0..n {\n        h = l2n2(&[a[t] * h[0] + b_u[t], a[t] * h[1] + b_u[t]]);\n        out.extend_from_slice(&h); // strictly sequential by construction\n    }\n    out\n}\n// Decision: the parallel form is bought only by REMOVING the state norm\n// (the paper's V2 rung) -- never by scanning the normalized recurrence.\n".to_string(),
        },

        // -- dynamic-kernel-params-break-prefix-scan -- the second App-I
        // boundary breaker (with
        // state-normalization-between-updates-breaks-associative-scan,
        // above): distilled from arXiv:2602.21204 "Test-Time Training with
        // KV Binding Is Secretly Linear Attention" (NVIDIA, ICML 2026),
        // Appendix I (the non-reducibility analysis); corpus record
        // ../katgpt-rs/.research/516_TTT_KVB_Secretly_Linear_Attention.md
        // (katgpt-rs commit 513088cd). Batch 87 / Plan 048 T3 / Issue 054
        // (R2). Grade-B discipline: the paper's throughput AND quality
        // numbers are LaCT end-to-end, never cite isolated; ZERO in-tree
        // firing population today (paper-distilled precedent = B79).
        KernelRule {
            rule_id: "dynamic-kernel-params-break-prefix-scan".to_string(),
            gpu_concept: "A first-order affine recurrence is only scan-eligible because the per-token pair (a_t, b_t) -- the kernel phi generally -- is a function of the TOKEN alone; the App-I breaker removes exactly that precondition: updating the kernel-function parameters Theta INSIDE the recurrence (Theta_t = f(Theta_{t-1}, h_t) -- test-time-training inner loops that fit the kernel during the forward are the canonical instance) makes phi history-dependent through nested nonlinearity chains (silu' nesting through the update: Theta_t depends on Theta_{t-1}, which depends on the state), so the state update is no longer expressible as a history sum, the pair-space composition is no longer associative, and a prefix-scan port SILENTLY computes a different operator -- both forms compile and run; the failure mode is divergent outputs, never an error. THE FIX IS TO STOP UPDATING: freeze Theta at layer load (a const or a prebuilt per-layer table) so only the STATE recurses and first-order-affine-recurrence-associative-scan's pair-space form applies verbatim; when Theta adaptation is wanted, the paper's measured reduction trajectory (Table 2) is the design table -- Variant 1 (update only the LAST fast-weight layer) measured best-or-near quality on every task (15.93 vs the 16.43 full-baseline LLM ppl) at 2.5x layer recurrent throughput, and Variant 2 (+ remove weight norm) is the FIRST shape that admits the chunk-parallel form -- weight-norm removal is what unlocks parallelism, and 16.31 ppl still beats the full baseline. PROVENANCE DISCIPLINE: theory-distilled from arXiv:2602.21204 App I; grade B -- the paper's throughput (4.0x parallel-form / 1.19x training) AND quality numbers are LaCT end-to-end runs (90M-760M from-scratch pretrains), never cite them as if isolated to this mechanism; zero in-tree firing population today (paper-distilled precedent = B79 itself). Distinct from first-order-affine-recurrence-associative-scan (the positive case: static-Theta affine => scan; this is the dynamic-Theta breaker), from zero-init-side-branch-frozen-base-path (freezes a DISTILLATION TEACHER base outside the recurrence -- a different frozen object for a different reason), and from hot-swap-weights-preserve-autotune-caches (replacing weights BETWEEN forwards while keeping caches alive -- a deployment concern, not a within-recurrence dependency).".to_string(),
            ref_shape: "// BROKEN: a TTT-style recurrence whose kernel param Theta is updated\n// per step FROM the state (Theta_t = f(Theta_{t-1}, h_{t-1})) --\n// phi(x; Theta_t) is then a function of the WHOLE history and no\n// per-token pair exists.\nfn silu(x: f32) -> f32 { x / (1.0 + (-x).exp()) }\n\nfn broken_recurrence(x: &[f32], eta: f32) -> Vec<f32> {\n    let (mut h, mut theta) = (0.0f32, 1.0f32); // theta mutated INSIDE the loop\n    x.iter().map(|&xt| {\n        theta += eta * silu(h) * xt;    // inner-loop fit: depends on the state\n        h = silu(xt * theta) * h + xt;  // a_t = phi_t(xt) carries all history\n        h\n    }).collect()\n}\n\n// WRONG PORT: pairs frozen at the INITIAL theta, then the B79 pair scan.\n// Compiles, runs, and SILENTLY computes a different operator -- the\n// recurrence's a_t used Theta_t (history-dependent through the nested\n// silu chain), not THETA_0; the pair composition here is NOT associative\n// in the recurrence's operator. Divergent outputs, no error, ever.\nfn broken_scan(x: &[f32], theta0: f32) -> Vec<f32> {\n    let mut pairs: Vec<(f32, f32)> =\n        x.iter().map(|&xt| (silu(xt * theta0), xt)).collect();\n    let mut stride = 1usize;\n    while stride < pairs.len() {\n        for i in (stride..pairs.len()).rev() {\n            let (a2, b2) = pairs[i];\n            let (a1, b1) = pairs[i - stride];\n            pairs[i] = (a2 * a1, a2 * b1 + b2); // (a2,b2) o (a1,b1) -- fine\n        }                                        // per se; the PAIRS are wrong\n        stride *= 2;\n    }\n    pairs.iter().map(|p| p.1).collect()\n}\n".to_string(),
            opt_pattern: "// LEGAL: Theta frozen at layer load -- a const (or a prebuilt per-layer\n// table, hot-swappable BETWEEN forwards); only the STATE recurses. The\n// per-token pair now depends on the TOKEN only, the composition is\n// associative, and the B79 pair-space prefix scan applies verbatim.\nconst THETA: f32 = 0.5; // frozen at layer load\n\nfn silu(x: f32) -> f32 { x / (1.0 + (-x).exp()) }\n\nfn legal_pairs(x: &[f32]) -> Vec<(f32, f32)> {\n    x.iter().map(|&xt| (silu(xt * THETA), xt)).collect() // token-only pairs\n}\n\nfn legal_scan(x: &[f32]) -> Vec<f32> {\n    let mut pairs = legal_pairs(x);\n    let mut stride = 1usize;\n    while stride < pairs.len() {\n        for i in (stride..pairs.len()).rev() {\n            let (a2, b2) = pairs[i];\n            let (a1, b1) = pairs[i - stride];\n            pairs[i] = (a2 * a1, a2 * b1 + b2); // combine = B79's\n        }\n        stride *= 2;\n    }\n    pairs.iter().map(|p| p.1).collect()\n}\n// If Theta must adapt (TTT-style fitting), the adaptation happens BETWEEN\n// forwards -- outer loop: fit, hot-swap the frozen table, then re-scan --\n// never inside the recurrence.\n".to_string(),
        },
    ]
}
